export function StatusBadge({ status }: { status: 'ok' | 'failed' | 'running' }) {
  const icon = status === 'failed' ? '!' : status === 'running' ? '…' : '✓';
  return <span className={'status status-' + status}>{icon} {status}</span>;
}

