type Job = { id: string; status: 'uploading' | 'processing' | 'done' | 'failed' };

export function UploadStatus({ job }: { job?: Job }) {
  if (!job) return <div><input type='file' /><button>Upload</button></div>;
  if (job.status === 'done') return <a href={'/transcripts/' + job.id}>Open transcript</a>;
  if (job.status === 'failed') return <div>Something went wrong <button>Retry</button></div>;
  return <div className='spinner'>Processing…</div>;
}

